    39→        Map<String, Object> envelope = new LinkedHashMap<>();
    40→        envelope.put("type", type);
    41→        envelope.put("timestamp", System.currentTimeMillis() / 1000.0);
    42→        envelope.put("player_number", playerNumber);
    43→        envelope.put("payload", payload);
    44→
    45→        String json = GSON.toJson(envelope);
    46→        log.debug("Emitting: {}", json);
    47→        wsServer.broadcastMessage(json);
