     9→import java.net.InetSocketAddress;
    10→import java.util.Collections;
    11→import java.util.Set;
    12→import java.util.concurrent.ConcurrentHashMap;
    13→
    14→/**
    15→ * WebSocket server that broadcasts JSON messages to all connected Python clients.
    16→ */
    17→public class BridgeWebSocketServer extends WebSocketServer {
    18→
    19→    private static final Logger log = LoggerFactory.getLogger(BridgeWebSocketServer.class);
    20→    private final Set<WebSocket> clients = Collections.newSetFromMap(new ConcurrentHashMap<>());
    21→
    22→    public BridgeWebSocketServer(int port) {
    23→        super(new InetSocketAddress("localhost", port));
    24→        setReuseAddr(true);
    25→    }
    26→
    27→    @Override
    28→    public void onOpen(WebSocket conn, ClientHandshake handshake) {
    29→        clients.add(conn);
    30→        log.info("Client connected ({} total)", clients.size());
    31→    }
    32→
    33→    @Override
    34→    public void onClose(WebSocket conn, int code, String reason, boolean remote) {
    35→        clients.remove(conn);
    36→        log.warn("Client disconnected ({} total)", clients.size());
    37→    }
    38→
    39→    @Override
    40→    public void onMessage(WebSocket conn, String message) {
    41→        // We don't expect messages from clients
    42→    }
    43→
    44→    @Override
    45→    public void onError(WebSocket conn, Exception ex) {
    46→        if (conn != null) {
    47→            clients.remove(conn);
    48→        }
    49→        log.error("WebSocket error: {}", ex.getMessage(), ex);
    50→    }
    51→
    52→    @Override
    53→    public void onStart() {
    54→        log.info("WebSocket server started on port {}", getPort());
    55→    }
    56→
    57→    /**
    58→     * Broadcast a JSON message to all connected clients.
    59→     */
    60→    public void broadcastMessage(String json) {
    61→        for (WebSocket client : clients) {
    62→            try {
    63→                if (client.isOpen()) {
    64→                    client.send(json);
    65→                }
    66→            } catch (Exception e) {
    67→                log.warn("Failed to send to client: {}", e.getMessage());
    68→                clients.remove(client);
    69→            }
    70→        }
    71→    }
    72→
    73→    public int getClientCount() {
    74→        return clients.size();
    75→    }
    76→}
